sys_script_include.script:
var MobileNumberValidation = Class.create();
MobileNumberValidation.prototype = {
    initialize: function() {},

    validateMobileNumber: function(mobileNumber) {
        // Check if mobile number is exactly 10 digits and doesn't start with 0
        var mobileRegex = /^[1-9]\d{9}$/;

        if (!mobileNumber) {
            return {
                valid: false,
                message: "Mobile number is required"
            };
        }

        if (!mobileRegex.test(mobileNumber)) {
            return {
                valid: false,
                message: "Mobile number must be exactly 10 digits and cannot start with 0"
            };
        }

        return {
            valid: true,
            message: ""
        };
    },

    type: 'MobileNumberValidation'
};
